const o = $input.first().json;
const items = (o.line_items || []).map(li => `- ${li.quantity}x ${li.title}`).join('\n');
const name = o.customer ? `${o.customer.first_name || ''} ${o.customer.last_name || ''}`.trim() : 'Guest';
return [{ json: { orderNumber: o.name, customer: name, items, total: `${o.total_price} ${o.currency}` } }];
